style.css:
@-moz-document domain("youtube.com") {
:root {
    /* Soft Flareon palette */
    --flare-peach: #FFB07C;
    --flare-orange: #FF9B6A;
    --flare-cream: #FFF0D4;
    --flare-soft: #FFE8B5;
    --flare-blush: #FF8E72;
    --flare-deep: #E07A5F;
    --flare-text: #4A3429;
    --flare-muted: #8B6B5A;
    --flare-panel: rgba(255, 245, 230, 0.78);
    --flare-panel-dark: rgba(255, 240, 220, 0.88);

    /* Keep your background image */
    --flare-bg-image: url(https://c.wallhere.com/photos/30/7c/Pok_mon_Flareon-1954237.jpg!d);
  }

  /* Base */
  html, body, ytd-app {
    background: #FFF8F0 var(--flare-bg-image) center / cover fixed no-repeat !important;
    color: var(--flare-text) !important;
  }

  /* Soft dreamy overlay (much gentler) */
  ytd-app::before {
    content: "";
    position: fixed;
    inset: 0;
    background: rgba(255, 245, 230, 0.55); /* soft cream veil */
    pointer-events: none;
    z-index: -1;
  }

  /* Make containers transparent */
  ytd-masthead,
  #background.ytd-masthead,
  ytd-guide-renderer,
  #guide-content,
  ytd-mini-guide-renderer,
  ytd-browse,
  ytd-watch-flexy,
  ytd-search,
  #page-manager,
  ytd-rich-grid-renderer,
  ytd-two-column-browse-results-renderer,
  #columns,
  #primary,
  #secondary,
  ytd-item-section-renderer,
  #content.ytd-app {
    background: transparent !important;
  }

  /* Sidebar – soft creamy panel */
  ytd-guide-renderer,
  #guide-content,
  ytd-mini-guide-renderer {
    background: var(--flare-panel) !important;
    backdrop-filter: blur(12px);
    border-radius: 0 24px 24px 0;
  }

  /* Header */
  ytd-masthead {
    background: var(--flare-panel-dark) !important;
    backdrop-filter: blur(14px);
    border-bottom: 2px solid rgba(255, 176, 124, 0.35) !important;
  }

  /* Search bar – super rounded & soft */
  ytd-searchbox,
  #search-input,
  .ytSearchboxComponentInputBox,
  #container.ytd-searchbox {
    background: rgba(255, 248, 240, 0.9) !important;
    border: 2px solid var(--flare-peach) !important;
    border-radius: 999px !important;
    color: var(--flare-text) !important;
    box-shadow: 0 4px 15px rgba(255, 155, 106, 0.15);
  }

  .ytSearchboxComponentSearchButton,
  #search-icon-legacy {
    background: linear-gradient(135deg, var(--flare-peach), var(--flare-blush)) !important;
    color: white !important;
    border-radius: 0 999px 999px 0 !important;
  }

  /* Chips – pill shaped & cute */
  yt-chip-cloud-chip-renderer,
  .ytChipShapeChip {
    background: rgba(255, 248, 240, 0.85) !important;
    border: 2px solid rgba(255, 176, 124, 0.4) !important;
    border-radius: 999px !important;
    color: var(--flare-text) !important;
    font-weight: 500 !important;
  }

  yt-chip-cloud-chip-renderer[selected],
  .ytChipShapeChip[aria-selected="true"] {
    background: linear-gradient(135deg, var(--flare-peach), var(--flare-orange)) !important;
    color: white !important;
    border-color: transparent !important;
    box-shadow: 0 4px 12px rgba(255, 155, 106, 0.3);
  }

  /* Buttons */
  ytd-button-renderer.style-primary,
  .yt-spec-button-shape-next--primary {
    background: linear-gradient(135deg, var(--flare-peach), var(--flare-blush)) !important;
    color: white !important;
    border-radius: 999px !important;
    font-weight: 600 !important;
    box-shadow: 0 4px 12px rgba(255, 142, 114, 0.25);
  }

  ytd-button-renderer.style-primary:hover,
  .yt-spec-button-shape-next--primary:hover {
    background: linear-gradient(135deg, var(--flare-orange), var(--flare-peach)) !important;
    transform: translateY(-1px);
    box-shadow: 0 6px 16px rgba(255, 142, 114, 0.35);
  }

  /* Progress bar – soft gradient */
  .ytp-play-progress,
  .ytp-swatch-background-color {
    background: linear-gradient(90deg, var(--flare-blush), var(--flare-peach), var(--flare-cream)) !important;
    border-radius: 4px;
  }

  .ytp-load-progress {
    background: rgba(255, 176, 124, 0.25) !important;
  }

  /* Text */
  #video-title,
  .title,
  yt-formatted-string,
  #channel-name,
  h1, h2, h3 {
    color: var(--flare-text) !important;
  }

  #metadata-line,
  .ytd-video-meta-block {
    color: var(--flare-muted) !important;
  }

  /* Active sidebar item */
  ytd-guide-entry-renderer[active],
  ytd-guide-entry-renderer:hover {
    background: linear-gradient(90deg, rgba(255, 176, 124, 0.35), transparent) !important;
    border-left: 4px solid var(--flare-peach) !important;
    border-radius: 0 16px 16px 0;
  }

  /* Scrollbar – soft peach */
  ::-webkit-scrollbar {
    width: 10px;
  }
  ::-webkit-scrollbar-track {
    background: transparent;
  }
  ::-webkit-scrollbar-thumb {
    background: linear-gradient(var(--flare-peach), var(--flare-blush));
    border-radius: 999px;
  }

  /* Icons soft cream-peach */
  yt-icon, .yt-icon {
    color: var(--flare-deep) !important;
  }

/* ===== Replace YouTube logo with Flareon GIF (bigger) ===== */

/* Hide the original YouTube logo */
ytd-topbar-logo-renderer #logo-icon,
ytd-topbar-logo-renderer #logo-icon-container,
ytd-topbar-logo-renderer svg,
ytd-topbar-logo-renderer img,
#logo-icon {
  display: none !important;
  opacity: 0 !important;
  visibility: hidden !important;
  width: 0 !important;
  height: 0 !important;
}

/* Bigger Flareon logo */
ytd-topbar-logo-renderer #logo {
  background: url(https://giffiles.alphacoders.com/130/130804.gif) no-repeat center !important;
  background-size: contain !important;
  width: 120px !important;        /* was 95px → bigger */
  height: 48px !important;        /* was 40px → bigger */
  min-width: 120px !important;
  margin-right: 12px !important;
  display: block !important;
}
  
/* ===== Flareon Progress Bar (Fixed + Bigger) ===== */

/* Soft Flareon gradient for the progress bar */
.ytp-play-progress,
.ytp-swatch-background-color {
  background: linear-gradient(90deg, 
    #FF8E72 0%, 
    #FFB07C 40%, 
    #FFD9A0 75%, 
    #FFF0D4 100%) !important;
  border-radius: 4px !important;
}

.ytp-load-progress {
  background: rgba(255, 176, 124, 0.25) !important;
}

/* Hide the default white circle completely */
.ytp-scrubber-button {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

/* Put the running Flareon on the actual moving scrubber button */
.ytp-scrubber-button {
  background: url(https://64.media.tumblr.com/b336c67e32749f23725d7d4da8419240/tumblr_orfg4zrnVv1vgoof9o1_r10_540.gifv) no-repeat center !important;
  background-size: contain !important;
  width: 70px !important;
  height: 70px !important;
  margin-left: -20px !important;
  margin-top: -30px !important;
  border: none !important;
  box-shadow: none !important;
  transform: scaleX(-1) !important; /* mirrored */
  z-index: 70 !important;
}

/* Optional: slightly bigger on hover */
.ytp-scrubber-button:hover {
  transform: scaleX(-1) scale(1.1) !important;
}
}
